import{H as e,V as t,et as n,j as r}from"./chunks/framework.C_EfTa_6.js";var i=JSON.parse(`{"title":"蜂窝模块","description":"","frontmatter":{"title":"蜂窝模块","order":30},"headers":[],"relativePath":"kernel/embed/device/wwan.md","filePath":"kernel/embed/device/wwan.md"}`),a={name:`kernel/embed/device/wwan.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="_4g-与-5g-模块" tabindex="-1">4G 与 5G 模块 <a class="header-anchor" href="#_4g-与-5g-模块" aria-label="Permalink to “4G 与 5G 模块”">​</a></h1><p>玩转接板时有一个经验观察：4G 模块（EC20、EC25、SIM7600）插在普通的 USB 转接板上几乎&quot;一插就准&quot;，而 5G 模块（RM500Q、RM520N）用同样的转接板经常起不来。这个差异不是玄学，而是两类模块在总线协议、功耗特性、驱动栈三个层面上的代际差异。</p><h2 id="总线协议-usb-与-pcie-mhi" tabindex="-1">总线协议：USB 与 PCIe+MHI <a class="header-anchor" href="#总线协议-usb-与-pcie-mhi" aria-label="Permalink to “总线协议：USB 与 PCIe+MHI”">​</a></h2><p>绝大多数 4G 模块走 USB 2.0/3.0 协议。模块内部有一个 USB 设备控制器，向主机呈现多个 USB 接口（一个用于 AT 命令的串口、一个用于拨号上网的网卡接口、一个用于 GNSS 的接口）。USB 协议自带完善的容错机制（握手、重传、流控）和热插拔管理——模块初始化失败可以重新枚举，时序要求宽松，普通转接板的走线质量完全够用。</p><p>5G 模块（高通 SDX55/SDX62 平台）的数据面走 PCIe + MHI 协议。PCIe 是主板级总线——对信号完整性、电源时序、Reset 时序都有严格到毫秒级的要求：上电顺序（先 1.8V 再 3.3V）、PERST# 释放时机、链路训练超时。普通的 4G 转接板没有为 PCIe 走线做阻抗匹配，也没有 PCIe 时钟源——5G 模块插上去最常见的失败模式就是&quot;PCIe 链路训练失败&quot;，模块永远起不来。MHI（Modem Host Interface）是高通定义的 PCIe 之上的通道协议——主机通过 MHI 通道传输 IP 报文和控制消息，这比 USB 的 CDC ECM 复杂一个量级，驱动栈的要求也更高。</p><h2 id="功耗-1a-与瞬时大电流" tabindex="-1">功耗：1A 与瞬时大电流 <a class="header-anchor" href="#功耗-1a-与瞬时大电流" aria-label="Permalink to “功耗：1A 与瞬时大电流”">​</a></h2><p>4G 模块的峰值电流约 1A——搜网发射时短暂拉高，但普通转接板的供电（USB 2.0 供 500mA、USB 3.0 供 900mA，外接电源的板子通常预留 2A 余量）绰绰有余。</p><p>5G 模块的功耗特性完全不同。sub-6GHz 的 5G 发射功率密度高，RM520 在搜网和上行突发时的瞬时电流可达 3-4A。劣质转接板的 DC-DC 芯片响应速度慢，瞬时大电流直接把电压拉垮（跌落 1V 以上）——模块检测到欠压立即复位，复位后重新搜网，再次大电流，再次欠压——表现为&quot;模块反复重启&quot;。这不是模块坏了，是供电设计跟不上模块的功耗突变。工程解法：转接板独立供电（12V 输入板载 5V 大电流 DC-DC）、在模块电源引脚就近放置大容量电解电容（1000μF 级）吸收瞬时电流尖峰。</p><h2 id="驱动栈-十几年与几年" tabindex="-1">驱动栈：十几年与几年 <a class="header-anchor" href="#驱动栈-十几年与几年" aria-label="Permalink to “驱动栈：十几年与几年”">​</a></h2><p>4G 模块的驱动在 Linux 内核中已经沉淀了十几年。USB 串口部分走 <code>option</code> 驱动（2004 年进入内核），QMI 接口走 <code>qmi_wwan</code> 驱动（2014 年进入内核），RNDIS/CDC ECM 走内核通用驱动。绝大多数 4G 模块插上即可识别——VID/PID 已在驱动支持列表，无需任何额外安装。</p><p>5G 模块的 MHI 驱动栈年轻得多：<code>mhi_pci_generic</code> 驱动 2020 年才进入内核主线，各模块厂商的固件下载协议、通道配置各不相同。更麻烦的是固件问题——5G 模块的固件复杂度远超 4G（毫米波波束管理、多载波聚合），模块出厂固件版本与驱动栈的兼容矩阵是常见的坑点：驱动支持但固件过旧导致数据面起不来，需要先用厂商工具刷固件。内核版本也是一个约束——<code>mhi_pci_generic</code> 的完整功能需要较新的内核（5.10+ 才稳定），旧内核（如某些路由器的 4.x 内核）根本没有 MHI 支持。</p><h2 id="转接板选购的工程结论" tabindex="-1">转接板选购的工程结论 <a class="header-anchor" href="#转接板选购的工程结论" aria-label="Permalink to “转接板选购的工程结论”">​</a></h2><p>4G 模块：任何正规转接板都能用，差异只在形态（Mini-PCIe/M.2/邮票孔）和天线接口。5G 模块：转接板必须明确标注&quot;支持 PCIe 模式&quot;——只有 USB 模式的 5G 模块（有些模块提供 USB 2.0 fallback，速度大幅受限）才能在普通板子上工作；PCIe 模式的模块需要板子具备 PCIe 走线优化、独立供电、以及正确的上电时序。Mini-PCIe 形态的 5G 模块（如 RM500Q 的 Mini-PCIe 版）尤其需要注意——Mini-PCIe 接口的 PCIe 信号是 x1 且很多转接板根本没有接 PCIe 信号线，只能走 USB 模式。</p><p>两类模块的差异本质是技术代际：4G 时代的蜂窝模块是&quot;USB 外设&quot;，5G 时代的蜂窝模块是&quot;PCIe 端点设备&quot;。从外设到端点的跨越，意味着对宿主硬件的信号完整性、电源设计和驱动栈的要求全面升级——转接板这个环节从&quot;无关紧要&quot;变成了&quot;决定性因素&quot;。</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};